SELECT "t10"."order_number", "t10"."line_no", "t10"."item", "t10"."quantity", "t10"."on_hand", "t10"."outage", "t10"."short", 'hold_sales' AS "route", 'shortfall' AS "context"
FROM (SELECT "order_number", "line_no", "item", "quantity", "on_hand", "outage", "quantity" - "on_hand" AS "short"
        FROM (SELECT "t6"."order_number", "t6"."customer", "t6"."channel", "t6"."fulfilling_warehouse", "t6"."value", "t6"."placed_date", "t6"."state", "t6"."line_no", "t6"."item", "t6"."quantity", "t6"."unit_price", "t6"."ext_sales_price", "t6"."warehouse", "t6"."sold_date", "t6"."customer0", "t6"."channel0", "t6"."as_of_date", "t6"."quantity_on_hand", "t6"."_ttrp_g_n8_0", "t6"."_ttrp_g_n8_1", "t7"."warehouse" AS "warehouse0", "t7"."from_date", "t7"."to_date", "t7"."reason", COALESCE("t6"."quantity_on_hand", 0) AS "on_hand", "t7"."warehouse" IS NOT NULL AS "outage"
                FROM (SELECT "t1"."order_number", "t1"."customer", "t1"."channel", "t1"."fulfilling_warehouse", "t1"."value", "t1"."placed_date", "t1"."state", "t1"."line_no", "t1"."item", "t1"."quantity", "t1"."unit_price", "t1"."ext_sales_price", "t1"."warehouse", "t1"."sold_date", "t1"."customer0", "t1"."channel0", "t5"."as_of_date", "t5"."quantity_on_hand", "t5"."_ttrp_g_n8_0", "t5"."_ttrp_g_n8_1"
                        FROM (SELECT "t0"."order_number", "t0"."customer", "t0"."channel", "t0"."fulfilling_warehouse", "t0"."value", "t0"."placed_date", "t0"."state", "sales_line"."line_no", "sales_line"."item", "sales_line"."quantity", "sales_line"."unit_price", "sales_line"."ext_sales_price", "sales_line"."warehouse", "sales_line"."sold_date", "sales_line"."customer" AS "customer0", "sales_line"."channel" AS "channel0"
                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                        FROM "order"
                                        WHERE "state" IN ('held', 'placed')) AS "t0"
                                    INNER JOIN "sales_line" ON "t0"."order_number" = "sales_line"."order_number") AS "t1"
                            LEFT JOIN (SELECT "t2"."as_of_date", "t2"."item", "t2"."warehouse", "t2"."quantity_on_hand", "t2"."_ttrp_g_n8_0", "t2"."_ttrp_g_n8_1"
                                FROM (SELECT "as_of_date", "item", "warehouse", "quantity_on_hand", CASE WHEN "item" IS NULL THEN 'n' ELSE 'v' || CAST("item" AS VARCHAR) END AS "_ttrp_g_n8_0", CASE WHEN "warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("warehouse" AS VARCHAR) END AS "_ttrp_g_n8_1"
                                        FROM "inventory") AS "t2"
                                    INNER JOIN (SELECT CASE WHEN "item" IS NULL THEN 'n' ELSE 'v' || CAST("item" AS VARCHAR) END AS "_ttrp_g_n8_0", CASE WHEN "warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("warehouse" AS VARCHAR) END AS "_ttrp_g_n8_1", MAX("as_of_date") AS "_ttrp_latest_n8"
                                        FROM "inventory"
                                        GROUP BY CASE WHEN "item" IS NULL THEN 'n' ELSE 'v' || CAST("item" AS VARCHAR) END, CASE WHEN "warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("warehouse" AS VARCHAR) END) AS "t4" ON "t2"."_ttrp_g_n8_0" = "t4"."_ttrp_g_n8_0" AND "t2"."_ttrp_g_n8_1" = "t4"."_ttrp_g_n8_1" AND "t2"."as_of_date" = "t4"."_ttrp_latest_n8") AS "t5" ON "t1"."item" = "t5"."item" AND "t1"."warehouse" = "t5"."warehouse") AS "t6"
                    LEFT JOIN (SELECT *
                        FROM "warehouse_outage"
                        WHERE "from_date" <= :as_of AND "to_date" >= :as_of) AS "t7" ON "t6"."warehouse" = "t7"."warehouse") AS "t8"
        WHERE "t8"."outage" OR "t8"."on_hand" < "t8"."quantity") AS "t10"
    INNER JOIN (SELECT "order_number"
        FROM (SELECT "t38"."order_number", "t38"."customer", "t38"."channel", "t38"."fulfilling_warehouse", "t38"."value", "t38"."placed_date", "t38"."state", COALESCE("t38"."n_short", 0) AS "n_short", COALESCE("t38"."n_price", 0) AS "n_price", COALESCE("t44"."n_due", 0) AS "n_due"
                FROM (SELECT "t26"."order_number", "t26"."customer", "t26"."channel", "t26"."fulfilling_warehouse", "t26"."value", "t26"."placed_date", "t26"."state", "t26"."n_short", "t37"."n_price"
                        FROM (SELECT "t12"."order_number", "t12"."customer", "t12"."channel", "t12"."fulfilling_warehouse", "t12"."value", "t12"."placed_date", "t12"."state", "t25"."n_short"
                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                        FROM "order"
                                        WHERE "state" IN ('held', 'placed')) AS "t12"
                                    LEFT JOIN (SELECT "order_number", COUNT("line_no") AS "n_short"
                                        FROM (SELECT "t20"."order_number", "t20"."customer", "t20"."channel", "t20"."fulfilling_warehouse", "t20"."value", "t20"."placed_date", "t20"."state", "t20"."line_no", "t20"."item", "t20"."quantity", "t20"."unit_price", "t20"."ext_sales_price", "t20"."warehouse", "t20"."sold_date", "t20"."customer0", "t20"."channel0", "t20"."as_of_date", "t20"."quantity_on_hand", "t20"."_ttrp_g_n8_0", "t20"."_ttrp_g_n8_1", "t21"."warehouse" AS "warehouse0", "t21"."from_date", "t21"."to_date", "t21"."reason", COALESCE("t20"."quantity_on_hand", 0) AS "on_hand", "t21"."warehouse" IS NOT NULL AS "outage"
                                                FROM (SELECT "t15"."order_number", "t15"."customer", "t15"."channel", "t15"."fulfilling_warehouse", "t15"."value", "t15"."placed_date", "t15"."state", "t15"."line_no", "t15"."item", "t15"."quantity", "t15"."unit_price", "t15"."ext_sales_price", "t15"."warehouse", "t15"."sold_date", "t15"."customer0", "t15"."channel0", "t19"."as_of_date", "t19"."quantity_on_hand", "t19"."_ttrp_g_n8_0", "t19"."_ttrp_g_n8_1"
                                                        FROM (SELECT "t14"."order_number", "t14"."customer", "t14"."channel", "t14"."fulfilling_warehouse", "t14"."value", "t14"."placed_date", "t14"."state", "sales_line0"."line_no", "sales_line0"."item", "sales_line0"."quantity", "sales_line0"."unit_price", "sales_line0"."ext_sales_price", "sales_line0"."warehouse", "sales_line0"."sold_date", "sales_line0"."customer" AS "customer0", "sales_line0"."channel" AS "channel0"
                                                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                                        FROM "order"
                                                                        WHERE "state" IN ('held', 'placed')) AS "t14"
                                                                    INNER JOIN "sales_line" AS "sales_line0" ON "t14"."order_number" = "sales_line0"."order_number") AS "t15"
                                                            LEFT JOIN (SELECT "t16"."as_of_date", "t16"."item", "t16"."warehouse", "t16"."quantity_on_hand", "t16"."_ttrp_g_n8_0", "t16"."_ttrp_g_n8_1"
                                                                FROM (SELECT "as_of_date", "item", "warehouse", "quantity_on_hand", CASE WHEN "item" IS NULL THEN 'n' ELSE 'v' || CAST("item" AS VARCHAR) END AS "_ttrp_g_n8_0", CASE WHEN "warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("warehouse" AS VARCHAR) END AS "_ttrp_g_n8_1"
                                                                        FROM "inventory") AS "t16"
                                                                    INNER JOIN (SELECT CASE WHEN "item" IS NULL THEN 'n' ELSE 'v' || CAST("item" AS VARCHAR) END AS "_ttrp_g_n8_0", CASE WHEN "warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("warehouse" AS VARCHAR) END AS "_ttrp_g_n8_1", MAX("as_of_date") AS "_ttrp_latest_n8"
                                                                        FROM "inventory"
                                                                        GROUP BY CASE WHEN "item" IS NULL THEN 'n' ELSE 'v' || CAST("item" AS VARCHAR) END, CASE WHEN "warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("warehouse" AS VARCHAR) END) AS "t18" ON "t16"."_ttrp_g_n8_0" = "t18"."_ttrp_g_n8_0" AND "t16"."_ttrp_g_n8_1" = "t18"."_ttrp_g_n8_1" AND "t16"."as_of_date" = "t18"."_ttrp_latest_n8") AS "t19" ON "t15"."item" = "t19"."item" AND "t15"."warehouse" = "t19"."warehouse") AS "t20"
                                                    LEFT JOIN (SELECT *
                                                        FROM "warehouse_outage"
                                                        WHERE "from_date" <= :as_of AND "to_date" >= :as_of) AS "t21" ON "t20"."warehouse" = "t21"."warehouse") AS "t22"
                                        WHERE "t22"."outage" OR "t22"."on_hand" < "t22"."quantity"
                                        GROUP BY "order_number") AS "t25" ON "t12"."order_number" = "t25"."order_number") AS "t26"
                            LEFT JOIN (SELECT "order_number0" AS "order_number", COUNT("line_no0") AS "n_price"
                                FROM (SELECT "t29"."order_number", "t29"."line_no", "t29"."item", "t29"."unit_price", "t29"."customer", "t29"."channel", "t29"."placed_date", "t33"."order_number" AS "order_number0", "t33"."line_no" AS "line_no0", "t33"."price"
                                        FROM (SELECT "sales_line1"."order_number", "sales_line1"."line_no", "sales_line1"."item", "sales_line1"."unit_price", "t28"."customer", "t28"."channel", "t28"."placed_date"
                                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                        FROM "order"
                                                        WHERE "state" IN ('held', 'placed')) AS "t28"
                                                    INNER JOIN "sales_line" AS "sales_line1" ON "t28"."order_number" = "sales_line1"."order_number") AS "t29"
                                            INNER JOIN (SELECT "t32"."order_number", "t32"."line_no", COALESCE("customer_price"."price", "price_list"."price") AS "price"
                                                FROM (SELECT "sales_line2"."order_number", "sales_line2"."line_no", "sales_line2"."item", "sales_line2"."unit_price", "t31"."customer", "t31"."channel", "t31"."placed_date"
                                                        FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                                FROM "order"
                                                                WHERE "state" IN ('held', 'placed')) AS "t31"
                                                            INNER JOIN "sales_line" AS "sales_line2" ON "t31"."order_number" = "sales_line2"."order_number") AS "t32"
                                                    LEFT JOIN "customer_price" ON "t32"."item" = "customer_price"."item" AND "t32"."customer" = "customer_price"."customer" AND "t32"."placed_date" >= "customer_price"."valid_from" AND ("customer_price"."valid_to" IS NULL OR "t32"."placed_date" <= "customer_price"."valid_to")
                                                    LEFT JOIN "price_list" ON "t32"."item" = "price_list"."item" AND "t32"."channel" = "price_list"."channel" AND "t32"."placed_date" >= "price_list"."valid_from" AND ("price_list"."valid_to" IS NULL OR "t32"."placed_date" <= "price_list"."valid_to")) AS "t33" ON "t29"."order_number" = "t33"."order_number" AND "t29"."line_no" = "t33"."line_no") AS "t34"
                                WHERE "t34"."price" IS NULL OR ABS("t34"."unit_price" - "t34"."price") > :tolerance
                                GROUP BY "order_number0") AS "t37" ON "t26"."order_number" = "t37"."order_number") AS "t38"
                    LEFT JOIN (SELECT "order_number", COUNT("invoice_id") AS "n_due"
                        FROM (SELECT "t40"."order_number", "t40"."customer", "t40"."channel", "t40"."fulfilling_warehouse", "t40"."value", "t40"."placed_date", "t40"."state", "invoice"."invoice_id", "invoice"."order_number" AS "order_number0", "invoice"."issued", "invoice"."due", "invoice"."amount", "invoice"."paid", "invoice"."status"
                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                        FROM "order"
                                        WHERE "state" IN ('held', 'placed')) AS "t40"
                                    INNER JOIN "invoice" ON "t40"."customer" = "invoice"."customer") AS "t41"
                        WHERE "t41"."status" = 'open' AND "t41"."due" < :as_of
                        GROUP BY "order_number") AS "t44" ON "t38"."order_number" = "t44"."order_number") AS "t45"
        WHERE "t45"."n_short" > 0 OR "t45"."n_price" > 0
        GROUP BY "order_number") AS "t48" ON "t10"."order_number" = "t48"."order_number"
